def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    my_last, opp_last = history[-1]
    d_opp = sum(1 for m, o in history if o == 'D')
    c_opp = n - d_opp
    d_me = sum(1 for m, o in history if m == 'D')

    if n < 2:
        return 'C'

    # First few rounds: cooperate unless opponent opened with defection.
    if n < 5:
        if d_opp == 0:
            return 'C'
        if opp_last == 'D' and my_last == 'C':
            return 'D'
        return 'C'

    # Opponent seems to have repented after initial defections: forgive.
    if d_opp <= 1 and n >= 6:
        return 'C'

    # Last rounds: cash in against cooperators, avoid being suckered.
    if n == 99:
        return 'D'
    if n >= 95:
        if c_opp * 100 >= n * 75:
            return 'D'
        return 'C'

    # Sustained defector detection: never reward.
    if d_opp * 100 >= n * 85 and c_opp <= 2:
        return 'D'

    # Recent window.
    w = history[-8:]
    rd = sum(1 for m, o in w if o == 'D')
    rc = len(w) - rd
    rmy_d = sum(1 for m, o in w if m == 'D')

    # Opponent fully cooperating recently: stay cooperative, rare probe.
    if rd == 0:
        if n > 25 and c_opp * 100 >= n * 90:
            if d_me * 100 <= n * 15 and rng.random() < 0.12:
                return 'D'
        return 'C'

    # Heavy recent defection: retaliate.
    if rd >= 5:
        return 'D'

    # Tit-for-tat foundation with limited forgiveness.
    if opp_last == 'D':
        if rd <= 2 and rc >= 4 and my_last == 'C':
            # Single recent defection: retaliate once.
            return 'D'
        if rd <= 2:
            return 'D'
        return 'D' if rng.random() < 0.7 else 'C'

    # Opponent cooperated last.
    if rd >= 3:
        # Some recent flare-up; punish proportionally.
        if rng.random() < 0.55:
            return 'D'
        return 'C'

    if rd == 1:
        # One recent defection but last was C: mostly cooperate, occasional punish.
        if rng.random() < 0.2:
            return 'D'
        return 'C'

    # Default: cooperate against generally cooperative opponent.
    if d_opp * 100 <= n * 20:
        return 'C'
    if d_opp * 100 >= n * 45:
        return 'D' if rng.random() < 0.7 else 'C'
    return 'C'
